const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v2.0/companies/1234/projects/1234/equipment_register/%7Bequipment_id%7D/attachment',
  qs: {resource_id: 'SOME_STRING_VALUE'},
  headers: {'Procore-Company-Id': 'SOME_INTEGER_VALUE', 'content-type': 'application/json'},
  body: {name: 'Test file', type: 'DOCUMENT'},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/1234/projects/1234/equipment_register/%7Bequipment_id%7D/attachment?resource_id=SOME_STRING_VALUE"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_INTEGER_VALUE" },
    },
    Content = new StringContent("{\"name\":\"Test file\",\"type\":\"DOCUMENT\"}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

